using namespace std;
void need(bool b,const char*s){if(!b)throw runtime_error(s);}
struct Graph{vector<int>a;int c;};
uint64_t capadd(uint64_t x,uint64_t y){uint64_t s=x+y,f=((s>>2)|(s>>3))&0x1111111111111111ULL;return(s&~(15*f))|(f<<2);}
vector<vector<int>> endpoints(const vector<int>&a){int n=a.size(),full=(1<<n)-1;vector<uint64_t>d((1<<n)*n);for(int v=0;v<n;v++)d[(1<<v)*n+v]=1ULL<<(4*v);for(int S=1;S<=full;S++)for(int v=0;v<n;v++){uint64_t x=d[S*n+v];if(!x)continue;int rem=a[v]&~S;while(rem){int b=rem&-rem;rem-=b;int w=__builtin_ctz((unsigned)b);auto &z=d[(S|b)*n+w];z=capadd(z,x);}}vector<vector<int>>M(n,vector<int>(n));for(int s=0;s<n;s++)for(int t=0;t<n;t++)M[s][t]=(d[full*n+t]>>(4*s))&15;return M;}
long long maxperm=0,totalcanon=0;
string canon(const vector<int>&a){int n=a.size();vector<int>col(n);for(int i=0;i<n;i++)col[i]=__builtin_popcount((unsigned)a[i]);{auto v=col;sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());for(auto&x:col)x=lower_bound(v.begin(),v.end(),x)-v.begin();}
 while(true){int k=*max_element(col.begin(),col.end())+1;vector<vector<int>>sig(n,vector<int>(k+1));for(int u=0;u<n;u++){sig[u][0]=col[u];for(int v=0;v<n;v++)if(a[u]>>v&1)sig[u][1+col[v]]++;}auto ss=sig;sort(ss.begin(),ss.end());ss.erase(unique(ss.begin(),ss.end()),ss.end());vector<int>nc(n);for(int u=0;u<n;u++)nc[u]=lower_bound(ss.begin(),ss.end(),sig[u])-ss.begin();col=nc;if((int)ss.size()==k)break;}
 int k=*max_element(col.begin(),col.end())+1;vector<vector<int>>groups(k);for(int v=0;v<n;v++)groups[col[v]].push_back(v);long long perms=1;for(auto&g:groups)for(int j=2;j<=(int)g.size();j++)perms*=j;maxperm=max(maxperm,perms);need(perms<=1000000,"refinement permutation budget unexpectedly large");vector<int>p;string best;auto rec=[&](auto&&self,int j)->void{if(j<k){auto g=groups[j];do{p.insert(p.end(),g.begin(),g.end());self(self,j+1);p.resize(p.size()-g.size());}while(next_permutation(g.begin(),g.end()));return;}string z(2*n,'\0');for(int u=0;u<n;u++){int row=0;for(int v=0;v<n;v++)if(a[p[u]]>>p[v]&1)row|=1<<v;z[2*u]=row&255;z[2*u+1]=row>>8;}if(best.empty()||z<best)best=z;};rec(rec,0);totalcanon++;return best;}
vector<int>decode(const string&k){vector<int>a;for(int i=0;i<(int)k.size();i+=2)a.push_back((unsigned char)k[i]+256*(unsigned char)k[i+1]);return a;}
int main(int argc,char**argv){need(argc==3,"usage own-records source-records");ofstream out(argv[1]);need(bool(out),"output open");map<int,map<string,int>>bank;vector<Graph>cur={{decode(canon({2,4,9,3})),1}};long long allmasks=0,allretained=0,parents=0;for(int n=4;n<=12;n++){array<int,4>hist{};long long bad3=0;for(auto&g:cur){string k=canon(g.a);need(bank[n].emplace(k,g.c).second,"duplicate canonical parent");hist[g.c]++;bool one=false;for(int r:g.a){int d=__builtin_popcount((unsigned)r);one|=d==1||d==n-2;}if(g.c==3&&!one)bad3++;out<<n<<","<<g.c;for(int r:g.a)out<<","<<r;out<<"\n";}need(bad3==0,"degree-one C3 failure");cout<<"order "<<n<<" C1 "<<hist[1]<<" C2 "<<hist[2]<<" C3 "<<hist[3]<<" max_refinement_permutations "<<maxperm<<endl;if(n==12)break;unordered_map<string,Graph>next;for(auto&g:cur){auto M=endpoints(g.a);parents++;int closing=0;for(int s=0;s<n;s++)for(int t=0;t<n;t++)if(g.a[t]>>s&1)closing+=M[s][t];need(closing==n*g.c,"parent cycle count via capped endpoint matrix");vector<int>outsum(n);for(int s=0;s<n;s++)outsum[s]=accumulate(M[s].begin(),M[s].end(),0);vector<int>cut(1<<n);for(int mask=1;mask<(1<<n);mask++){int v=__builtin_ctz((unsigned)mask),old=mask^(1<<v);int z=cut[old]+outsum[v];for(int bits=old;bits;bits&=bits-1){int u=__builtin_ctz((unsigned)bits);z-=M[u][v]+M[v][u];}need(z>=0,"negative directed cut");cut[mask]=z;if(mask==(1<<n)-1){need(z==0,"full cut");continue;}allmasks++;if(z>3)continue;need(z>=1,"mixed extension strong");allretained++;auto a=g.a;a.push_back(mask);for(int u=0;u<n;u++)if(!(mask>>u&1))a[u]|=1<<n;string key=canon(a);auto it=next.find(key);if(it==next.end())next.emplace(key,Graph{decode(key),z});else need(it->second.c==z,"isomorphic counts disagree");}}
 cur.clear();for(auto&kv:next)cur.push_back(move(kv.second));}
 out.close();ifstream src(argv[2]);need(bool(src),"source record open");map<int,map<string,int>>seen;string line;long long comparisons=0;while(getline(src,line)){replace(line.begin(),line.end(),',',' ');vector<int>x;size_t at=0;while(at<line.size()){while(at<line.size()&&line[at]==' ')at++;if(at==line.size())break;size_t end;int v=stoi(line.substr(at),&end);x.push_back(v);at+=end;}need(x.size()>=2&&x.size()==size_t(x[0]+2),"source row format");int n=x[0],c=x[1];vector<int>a(x.begin()+2,x.end());string key=canon(a);need(seen[n].emplace(key,c).second,"source contains isomorphic duplicate");need(bank.at(n).at(key)==c,"source graph missing/mismatch in independent bank");comparisons++;}need(seen==bank,"complete source graph-set disagreement");cout<<"PASS full_graph_set_isomorphism_comparisons "<<comparisons<<" parent_endpoint_matrices "<<parents<<" all_unpruned_mixed_masks "<<allmasks<<" retained_labelled_extensions "<<allretained<<" maximum_refinement_permutations "<<maxperm<<"\n";return 0;}
